    /**
     * Method to retrieve the Floor via FloorFetchOneSummary
     * @param 	summary FloorFetchOneSummary 
     * @return 	FloorFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Floor getFloor( FloorFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "FloorFetchOneSummary arg cannot be null" );
    	
    	Floor entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Floor
        	// --------------------------------------
        	CompletableFuture<Floor> futureEntity = queryGateway.query(new FindFloorQuery( new LoadFloorFilter( summary.getFloorId() ) ), ResponseTypes.instanceOf(Floor.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Floor with id " + summary.getFloorId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


